// чтение и блокировки в порядке старого кода (server/internal/billing/service, BR-005).
// Laravel: app/Services/AgentTariffPurchaseService.php purchase(), purchaseMinutes(), startPackage(), sell();
// app/Services/GuestSessions.php sell(); app/Services/ComputerReservations.php blocking(), markArrivedBy().
// Tariff::query()->lockForUpdate()->findOrFail(): без мягко удалённых (SoftDeletes).
func (q *Queries) LockTariffForPurchase(ctx context.Context, arg LockTariffForPurchaseParams) (LockTariffForPurchaseRow, error) {
	row := q.db.QueryRow(ctx, lockTariffForPurchase, arg.ClubID, arg.ID)
	var i LockTariffForPurchaseRow
	err := row.Scan(
		&i.ID,
		&i.Name,
		&i.DurationMinutes,
		&i.Price,
		&i.PaymentMethod,
		&i.DiscountEnabled,
		&i.IsActive,
		&i.UsageLimitEnabled,
		&i.UsageLimitMinutes,
		&i.QuantityLimitEnabled,
		&i.QuantityLimit,
		&i.UserRoles,
		&i.SalePeriods,
		&i.ValidityPeriods,
	)
	return i, err
}

const lockTimePackage = `-- name: LockTimePackage :one
SELECT id, user_id, tariff_id, name, minutes_left, expires_at
FROM time_packages
WHERE club_id = $1 AND user_id = $2 AND id = $3
FOR UPDATE
`

type LockTimePackageParams struct {
	ClubID int64 `json:"club_id"`
	UserID int64 `json:"user_id"`
	ID     int64 `json:"id"`
}

type LockTimePackageRow struct {
	ID          int64     `json:"id"`
	UserID      int64     `json:"user_id"`
	TariffID    *int64    `json:"tariff_id"`
	Name        string    `json:"name"`
	MinutesLeft int64     `json:"minutes_left"`
	ExpiresAt   time.Time `json:"expires_at"`
}

// TimePackage::query()->where('user_id', …)->lockForUpdate()->findOrFail().
func (q *Queries) LockTimePackage(ctx context.Context, arg LockTimePackageParams) (LockTimePackageRow, error) {
	row := q.db.QueryRow(ctx, lockTimePackage, arg.ClubID, arg.UserID, arg.ID)
	var i LockTimePackageRow
	err := row.Scan(
		&i.ID,
		&i.UserID,
		&i.TariffID,
		&i.Name,
		&i.MinutesLeft,
		&i.ExpiresAt,
	)
	return i, err
}

const markReservationsArrived = `-- name: MarkReservationsArrived :exec
UPDATE computer_reservations
SET arrived_at = $1, updated_at = $1
WHERE club_id = $2
  AND club_computer_id = $3
  AND user_id = $4
  AND cancelled_at IS NULL AND arrived_at IS NULL
  AND starts_at < $5 AND ends_at > $6
`

type MarkReservationsArrivedParams struct {
	Now        *time.Time `json:"now"`
	ClubID     int64      `json:"club_id"`
	ComputerID int64      `json:"computer_id"`
	UserID     *int64     `json:"user_id"`
	Until      time.Time  `json:"until"`
	FromAt     time.Time  `json:"from_at"`
}

// ComputerReservations::markArrivedBy(): своя бронь клиента на это время выполнена.
func (q *Queries) MarkReservationsArrived(ctx context.Context, arg MarkReservationsArrivedParams) error {
	_, err := q.db.Exec(ctx, markReservationsArrived,
		arg.Now,
		arg.ClubID,
		arg.ComputerID,
		arg.UserID,
		arg.Until,
		arg.FromAt,
	)
	return err
}

const setBillingRequestResponse = `-- name: SetBillingRequestResponse :exec
UPDATE billing_requests
SET response = $1
WHERE club_id = $2 AND idempotency_key = $3
`

type SetBillingRequestResponseParams struct {
	Response       json.RawMessage `json:"response"`
	ClubID         int64           `json:"club_id"`
	IdempotencyKey string          `json:"idempotency_key"`
}

func (q *Queries) SetBillingRequestResponse(ctx context.Context, arg SetBillingRequestResponseParams) error {
	_, err := q.db.Exec(ctx, setBillingRequestResponse, arg.Response, arg.ClubID, arg.IdempotencyKey)
	return err
}

const setComputerSession = `-- name: SetComputerSession :exec
UPDATE club_computers
SET current_session_id = $1,
    current_session_user_id = $2,
    session_guest = $3,
    session_ends_at = $4,
    updated_at = $5
WHERE club_id = $6 AND id = $7
`

type SetComputerSessionParams struct {
	SessionID     *string    `json:"session_id"`
	SessionUserID *int64     `json:"session_user_id"`
	SessionGuest  bool       `json:"session_guest"`
	SessionEndsAt *time.Time `json:"session_ends_at"`
	Now           *time.Time `json:"now"`
	ClubID        int64      `json:"club_id"`
	ID            int64      `json:"id"`
}

// Начало или продление сессии: sell() / GuestSessions::sell() ($computer->update([...])).
func (q *Queries) SetComputerSession(ctx context.Context, arg SetComputerSessionParams) error {
	_, err := q.db.Exec(ctx, setComputerSession,
		arg.SessionID,
		arg.SessionUserID,
		arg.SessionGuest,
		arg.SessionEndsAt,
		arg.Now,
		arg.ClubID,
		arg.ID,
	)
	return err
}

const setTotalSpent = `-- name: SetTotalSpent :exec
UPDATE club_memberships
SET total_spent = $1, updated_at = $2
WHERE club_id = $3 AND user_id = $4
`

type SetTotalSpentParams struct {
	TotalSpent int64      `json:"total_spent"`
	Now        *time.Time `json:"now"`
	ClubID     int64      `json:"club_id"`
	UserID     int64      `json:"user_id"`
}

// LoyaltyProgram::subtractSpending(): новое значение считает bonus.SubtractSpending под блокировкой строки.
func (q *Queries) SetTotalSpent(ctx context.Context, arg SetTotalSpentParams) error {
	_, err := q.db.Exec(ctx, setTotalSpent,
		arg.TotalSpent,
		arg.Now,
		arg.ClubID,
		arg.UserID,
	)
	return err
}
